create table if not exists public.timeline_daw_normalization_approvals(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,proof_id text not null references public.timeline_daw_normalization_proofs(id) on delete cascade,revision integer not null,decision text not null check(decision in('approved','rejected','revoked')),proof_checksum text not null,recipe_checksums jsonb not null,artifact_checksums jsonb not null,master_checksum text not null,dependency_checksum text not null,notes text not null default '',created_at timestamptz not null default now());alter table public.timeline_daw_normalization_approvals enable row level security;create policy timeline_daw_normalization_approvals_owner on public.timeline_daw_normalization_approvals for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create table if not exists public.timeline_daw_normalization_retention_receipts(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,revision integer not null,decision text not null check(decision in('retain','prune')),artifact_checksums jsonb not null,deleted_paths jsonb not null default '[]'::jsonb,created_at timestamptz not null default now());alter table public.timeline_daw_normalization_retention_receipts enable row level security;create policy timeline_daw_normalization_retention_owner on public.timeline_daw_normalization_retention_receipts for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());